Import ListNotations. Import AX2. Import AX2B. Import AX2S.
Unset Lia Cache. Unset Nia Cache. Unset Nra Cache.
Open Scope Z_scope.

Module PB.
Abbreviation RSEGS := PML.RSEGS.
Abbreviation mem := (word -> option byte).
Definition uv (E : env) (e : expr) : Z := ltac2:(Rpl.RP.run_i (rplG ()) 2 "S00$E;R+0$e;R+1!2'2!1,3|600;!2'4#2#1").

(* [comment removed for export] *)
Lemma uv_range : forall E e, 0 <= uv E e < 2 ^ 64.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S60!2'4#2#1|600;!2'2!1,310|10;!2':!1,;3!1,;1!2'<#2#1$E;R+0$e;R+1vd&H;R!1'50!2+6!2'7,82!2'924#1!2+6!2'7,85!2'954").
Qed.
Lemma uv_eaddz : forall E e z, uv E (APC.eaddz e z) = (uv E e + z) mod 2 ^ 64.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S@0|600;!1,30!1+?1!2'4#3#2!1,B#1!2'4#34!3'@,A35!2'21!2'4#4#3|10;!2':!1,;8!1,;0!2'D!2'E7#29!2'213!2'D!2'E;!2'2159$z;R+=!3+C+=#1:!2'D#1'F!2'D!2'E;#19$E;R+0$e;R+1$z;R+=vd!6'>26$b;R2!3+C+=!2'21#1:!6'>+=<=vd!6'>+=>$z;R+=!3+C+=!2'D!2'E7#19:vd!6'>+=?=!2,G+=?!2'D!2'E;!2'D#199!3'H#1;9!3+C+=!2'D!2'E;>9?!2'21!2'I1#1!1'J#1!3+C+=<?!2'216!2'K35!2'4#3!3'L,A#24!4'M#3,A#24!3+C+=!2'<#3!2'N#2#1!2'D!2'E!2'<#3#2#19").
Qed.
Lemma uv_eadd : forall E a b, uv E (APC.eadd a b) = (uv E a + uv E b) mod 2 ^ 64.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S:0|600;!1,30!1+?1!2'4#3#2!2'4#3#1!3'@,A34|10;!2':!1,;6!1,;0!2'D!2'E!2'21!2'4#4#3!2'21!2'4#4#27!2'D!2'E!2'213!2'2147$E;R+0$a;R+1$b;R+1vd!6'>25$b;R2!3+C+=!2'21#18!6'>+=9$z;R+=!3+C+=#18!2,G+=9!2'215!2'K34!2'4#3!3'L,A#2#1!4'M#3,A#2#1!3+C+=!2'<#3!2'O#2#1!2'D!2'E!2'<#3#2!2'<#3#17").
Qed.
Lemma uv_esub : forall E a b, uv E (APC.esub a b) = (uv E a - uv E b) mod 2 ^ 64.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S:0|600;!1,30!1+?1!2'4#3#2!2'4#3#1!3'@,P34|10;!2':!1,;6!1,;0!2'D!2'Q!2'21!2'4#4#3!2'21!2'4#4#27!2'D!2'Q!2'213!2'2147$E;R+0$a;R+1$b;R+1vd!6'>25$b;R2!3+C+=!2'21#18!6'>+=9$z;R+=!3+C+=#18!2,G+=9!2'215!2'R34!2'4#3!3'L,P#2#1!4'M#3,P#2#1!3+C+=!2'<#3!2'S#2#1!2'D!2'Q!2'<#3#2!2'<#3#17").
Qed.
Lemma uv_escale : forall E c e, uv E (APC.escale c e) = (c * uv E e) mod 2 ^ 64.
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S@0|600;!1,30!1+?1!1,B#2!2'4#33!2'4#3#1!4'T1,U45!2'21!2'4#4#2|10;!2':!1,;8!1,;0!2'D!2'V#379!2'215!2'D!2'V!2'214;9$z;R+=!3+C+=#1:!2'D#2'F!2'D!2'V#2;9$E;R+0$c;R+=$e;R+1vd!6'>26$b;R2!3+C+=!2'21#1:!6'>+=<=vd!6'>+=>$z;R+=!3+C+=!2'D!2'V#179:vd!6'>+=?=!2,G+=?!2'D!2'V!2'D#29;9!3'W#2;9!3+C+=!2'D!2'V>;9?!2'21!2'I1#2!1'J#2!3+C+=<?!2'216!2'X45!2'4#3!3'Y,U3#1!4'Z#3,U3#1!3+C+=!2'<#3!2'[#2#1!2'D!2'V#2!2'<#3#19").
Qed.

