Lemma win_arith : forall q n wseg wlen, 0 <= q < 2 ^ 64 -> 0 <= n <= 16384 -> 4096 <= wseg -> 0 <= wlen -> wseg + wlen <= 2 ^ 47 ->
  0 <= (q - wseg) mod 2 ^ 64 <= 16384 -> 0 <= ((wseg + wlen) mod 2 ^ 64 - (q + n) mod 2 ^ 64) mod 2 ^ 64 <= 16384 ->
